/* global ASSETS */

const MAX_POINTS = 300000;
const CONSENT_VERSION = '2026-10-08';
const SATISFACTION_OPTIONS = new Set([
  'Sim, estou satisfeito e gostaria de manter o mesmo fundo',
  'Mais ou menos, estou aberto a conhecer outros fundos',
  'Não, quero conhecer outros fundos'
]);

function json(data, status = 200) {
  return Response.json(data, {
    status,
    headers: { 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' }
  });
}

function validText(value, min, max) {
  return typeof value === 'string' && value.trim().length >= min && value.trim().length <= max;
}

async function saveLead(request, env) {
  const origin = request.headers.get('Origin');
  if (origin && origin !== new URL(request.url).origin) return json({ error: 'forbidden' }, 403);
  if (!request.headers.get('Content-Type')?.toLowerCase().startsWith('application/json')) {
    return json({ error: 'invalid_content_type' }, 415);
  }
  if (Number(request.headers.get('Content-Length')) > 5000) return json({ error: 'too_large' }, 413);

  let input;
  try {
    const body = await request.text();
    if (new TextEncoder().encode(body).length > 5000) return json({ error: 'too_large' }, 413);
    input = JSON.parse(body);
  } catch {
    return json({ error: 'invalid_json' }, 400);
  }

  if (!input || typeof input !== 'object' || Array.isArray(input) ||
      !/^[0-9a-f-]{36}$/i.test(input.submissionId || '') ||
      !Number.isSafeInteger(input.amountCents) || input.amountCents <= 0 || input.amountCents > 1_000_000_000_000 ||
      !validText(input.name, 2, 120) || !validText(input.email, 5, 254) ||
      !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.email.trim()) ||
      !/^\d{10,11}$/.test(input.phone || '') ||
      !validText(input.institution, 2, 150) ||
      !SATISFACTION_OPTIONS.has(input.satisfaction) ||
      input.consent !== true || input.consentVersion !== CONSENT_VERSION) {
    return json({ error: 'invalid_fields' }, 400);
  }
  if (!env.DB) return json({ error: 'temporarily_unavailable' }, 503);

  const points = Math.min(MAX_POINTS, Math.floor(input.amountCents / 10_000_000) * 10000);
  try {
    await env.DB.prepare(`
      INSERT INTO leads (id, name, email, phone, amount_cents, institution, satisfaction, points, consent_version)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        updated_at = CURRENT_TIMESTAMP,
        name = excluded.name,
        email = excluded.email,
        phone = excluded.phone,
        amount_cents = excluded.amount_cents,
        institution = excluded.institution,
        satisfaction = excluded.satisfaction,
        points = excluded.points,
        consent_version = excluded.consent_version
    `).bind(
      input.submissionId,
      input.name.trim(),
      input.email.trim().toLowerCase(),
      input.phone,
      input.amountCents,
      input.institution.trim(),
      input.satisfaction,
      points,
      CONSENT_VERSION
    ).run();
    return json({ saved: true, points }, 201);
  } catch {
    return json({ error: 'temporarily_unavailable' }, 503);
  }
}

function serveAsset(pathname, headOnly) {
  const path = pathname === '/' ? '/index.html' : pathname;
  const asset = ASSETS[path];
  if (!asset) return new Response('Not found', { status: 404 });
  const bytes = Uint8Array.from(atob(asset.base64), character => character.charCodeAt(0));
  return new Response(headOnly ? null : bytes, {
    headers: {
      'Content-Type': asset.type,
      'Cache-Control': 'public, max-age=300',
      'X-Content-Type-Options': 'nosniff'
    }
  });
}

export default {
  async fetch(request, env) {
    const pathname = new URL(request.url).pathname;
    if (pathname === '/api/leads') {
      if (request.method !== 'POST') return json({ error: 'method_not_allowed' }, 405);
      return saveLead(request, env);
    }
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return new Response('Method not allowed', { status: 405 });
    }
    return serveAsset(pathname, request.method === 'HEAD');
  }
};
